WITH lines AS (SELECT id, customer_id, created_at, pos, entry.product_id, entry.price, entry.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) e AS pos, entry), joined AS (SELECT s.customer_id, s.created_at, s.product_id, d.age, d.signup_date, d.segment FROM lines s INNER JOIN customers d ON s.customer_id = d.id), with_dims AS (SELECT s.*, d.signup_date AS customer_signup_date, d.name FROM joined s LEFT JOIN customers d ON s.customer_id = d.id), joined_carts AS (SELECT a.customer_id, a.product_id, a.age, a.segment, c.city, c.name AS customer_name, c.signup_date AS customer_signup_date_2 FROM with_dims a INNER JOIN customers c ON a.customer_id = c.id WHERE c.credit_limit BETWEEN 9000 AND 13900) SELECT product_id, segment, customer_name, customer_signup_date_2 FROM joined_carts ORDER BY customer_signup_date_2 DESC NULLS LAST;
